const e={"home.about.card.list.0":"ಉತ್ಪನ್ನ ದಿಕ್ಕು ಸಂಶೋಧನೆ ಮತ್ತು ಮಾನ್ಯತೆ (ಚಾಲುದಲ್ಲಿದೆ)","home.about.card.list.1":"ಮೂಲ ಸಾಮರ್ಥ್ಯ ಅಭಿವೃದ್ಧಿ: ಎಂಜಿನಿಯರಿಂಗ್ ವ್ಯವಸ್ಥೆ / ಡೇಟಾ ಮತ್ತು ಸೇವಾ ಸಾಮರ್ಥ್ಯಗಳು / ಮೂಲಸೌಕರ್ಯ","home.about.card.list.2":"ಪ್ರೋಟೋಟೈಪಿಂಗ್ ಮತ್ತು ವೇಗದ ಪುನರಾವೃತ್ತ: ಆಲೋಚನೆಯಿಂದ ಬಳಸಬಹುದಾದ ಆವೃತ್ತಿಗೆ","home.about.card.list.3":"ಅನುಕೂಲತೆ ಮತ್ತು ಭದ್ರತೆ: ಡೇಟಾ ಭದ್ರತೆ ಮತ್ತು ಗೌಪ್ಯತಾ ರಕ್ಷಣೆಯನ್ನು ಒತ್ತಿಸುತ್ತಿದೆ","home.about.card.note":"ವ್ಯವಹಾರದ ವ್ಯಾಪ್ತಿಯು ಇನ್ನೂ ಅನ್ವೇಷಣಾ ಹಂತದಲ್ಲಿರುವುದರಿಂದ...","home.about.card.title":"ನಾವು ಏನು ಮಾಡುತ್ತಿದ್ದೇವೆ?","home.about.desc.0":"ನಾವು ಸ್ವಯಂ-ಶೋಧನೆಗೆ ಕೇಂದ್ರೀಕೃತವಾದ ನೆಟ್ವರ್ಕ್ ತಂತ್ರಜ್ಞಾನ ಕಂಪನಿಯಾಗಿದೆ...","home.about.desc.1":"ಪ್ರಸ್ತುತ ವ್ಯಾಪಾರ ವ್ಯಾಪ್ತಿಯು ಇನ್ನೂ ನಿರಂತರ ಅನ್ವೇಷಣೆಯ ಅಡಿಯಲ್ಲಿ ಇದೆ...","home.about.hl.0.num":"ಸ್ವಯಂ ಅಭಿವೃದ್ಧಿಪಡಿಸಿದ ಮೊದಲ","home.about.hl.0.text":"ತಮ್ಮದೇ ಆದ ಉತ್ಪನ್ನಗಳು ಮತ್ತು ವ್ಯಾಪಾರದಲ್ಲಿ ನಿರಂತರ ಹೂಡಿಕೆ.","home.about.hl.1.num":"ಸ್ಥಿರ ಪುನರಾವೃತ್ತ","home.about.hl.1.text":"ಇಂಜಿನಿಯರಿಂಗ್ ಗುಣಮಟ್ಟ, ನಿರ್ವಹಣಾ ಸಾಮರ್ಥ್ಯ ಮತ್ತು ವಿಸ್ತರಣೀಯತೆಯನ್ನು ಒತ್ತಿಸಿ.","home.about.hl.2.num":"ನಿರಂತರವಾಗಿ ಅನ್ವೇಷಿಸುತ್ತಿರುವ","home.about.hl.2.text":"ವ್ಯವಹಾರ ದಿಕ್ಕುಗಳ ಚಲನೆಯು ಹಂತ ಹಂತವಾಗಿ ಸ್ಪಷ್ಟ ಗಡಿಗಳನ್ನು ರೂಪಿಸುತ್ತದೆ.","home.about.title":"ನಮ್ಮ ಬಗ್ಗೆ","home.brand.en":"ಟ್ರೀಹೌಸ್ ಟೆಕ್ · ಶಾಂಘೈ","home.common.city":"ಶಾಂಘೈ · SHANGHAI","home.common.company":"上海树下小屋网络科技有限公司","home.common.email":"house@sxxw.site","home.common.email_mailto":"mailto:house@sxxw.site","home.contact.hint":"ನೀವು ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಲು ಅಗತ್ಯವಿದ್ದರೆ, ದಯವಿಟ್ಟು ಇಮೇಲ್ ಮೂಲಕ ಸಂಪರ್ಕಿಸಿ...","home.contact.label.city":"ನಗರ","home.contact.label.company":"ಕಂಪನಿಯ ಹೆಸರು","home.contact.label.email":"ಇಮೇಲ್","home.contact.title":"ಸಂಪರ್ಕ ಮಾಹಿತಿ","home.footer.legal":"© 2025 上海树下小屋网络科技有限公司","home.footer.links.about":"ನಮ್ಮ ಬಗ್ಗೆ","home.footer.links.contact":"ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ","home.footer.links.home":"ಮನೆ","home.footer.slogan":"ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿಯ ಮೇಲೆ ಕೇಂದ್ರೀಕೃತವಾಗಿರಿ · ನಿರಂತರ ಅನ್ವೇಷಣೆ · ಸ್ಥಿರ ಪುನಾವೃತ್ತ","home.hero.cta.about":"ನಮ್ಮ ಬಗ್ಗೆ ಹೆಚ್ಚು ತಿಳಿಯಿರಿ →","home.hero.cta.contact":"ಸಂಪರ್ಕ ಮಾಹಿತಿ","home.hero.desc":"ನಾವು ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆಗೆ ಕೇಂದ್ರೀಕೃತವಾದ ನೆಟ್‌ವರ್ಕ್ ತಂತ್ರಜ್ಞಾನ ಕಂಪನಿಯಾಗಿದೆ. ನಾವು ಅಮೂಲ್ಯ ಉತ್ಪನ್ನ ದಿಕ್ಕುಗಳು ಮತ್ತು ತಾಂತ್ರಿಕ ಕಾರ್ಯಗತಗೊಳಿಸುವ ಮಾರ್ಗಗಳನ್ನು ನಿರಂತರವಾಗಿ ಅನ್ವೇಷಿಸುತ್ತೇವೆ, ದೀರ್ಘಕಾಲದ ಪುನರಾವೃತ್ತ ಮತ್ತು ಸ್ಥಿರ ವಿತರಣೆಯನ್ನು ಗುರಿಯಾಗಿಸಿಕೊಂಡಿದ್ದೇವೆ.","home.hero.glass":'ದಿಕ್ಕು ಅನ್ವೇಷಣೆ → ಇಂಜಿನಿಯರಿಂಗ್ ಕಾರ್ಯಗತಗೊಳಣೆ → ಉತ್ಪನ್ನ ಶುದ್ಧೀಕರಣ <span class="dot"></span> ದೀರ್ಘಕಾಲಿಕತೆ / ಸ್ಥಿರ ವಿತರಣಾ',"home.hero.meta.0.label":"ಉತ್ಪನ್ನ ಮತ್ತು ಇಂಜಿನಿಯರಿಂಗ್ ಕೇಂದ್ರೀಕೃತ","home.hero.meta.0.num":"ಸ್ವಯಂ ಅಭಿವೃದ್ಧಿ","home.hero.meta.1.label":"ನಿರಂತರ ಪುನರಾವೃತ್ತ ಮತ್ತು ಸುಧಾರಣೆ","home.hero.meta.1.num":"ದೀರ್ಘಕಾಲಿಕ","home.hero.meta.2.label":"ಗುಣಮಟ್ಟ ಮತ್ತು ಅನುಕೂಲತೆಯನ್ನು ಒತ್ತಿಸಿ","home.hero.meta.2.num":"ಸ್ಥಿರ","home.hero.mini.foot":"* ಪ್ರಸ್ತುತ ಅಧಿಕೃತ ವೆಬ್‌ಸೈಟ್ ಒಂದು ಮೂಲ ಪರಿಚಯ ಪುಟವಾಗಿದೆ, ಮತ್ತು ವ್ಯವಹಾರವು ಮುಂದುವರಿಯುವಂತೆ ವಿಷಯವನ್ನು ನಿರಂತರವಾಗಿ ನವೀಕರಿಸಲಾಗುತ್ತದೆ.","home.hero.mini.head":"ಟಿಪ್","home.hero.mini.main":"ನಿರಂತರವಾಗಿ ವ್ಯಾಪಾರ ದಿಕ್ಕುಗಳನ್ನು ಅನ್ವೇಷಿಸುತ್ತಿರುವುದು","home.hero.mini.stats.0.k":"ಕೇಂದ್ರಿತ","home.hero.mini.stats.0.v":"ಸ್ವಯಂ ಅಭಿವೃದ್ಧಿ ಮಾಡಿದ ಉತ್ಪನ್ನ","home.hero.mini.stats.1.k":"ರೂಪ","home.hero.mini.stats.1.v":"ಹೆಚ್ಚಾಗಿ ಸ್ಪಷ್ಟಪಡಿಸಿ","home.hero.mini.stats.2.k":"ರಿದಮ್","home.hero.mini.stats.2.v":"ಆವೃತ್ತಿ ಪ್ರಗತಿ","home.hero.mini.stats.3.k":"ಗುರಿ","home.hero.mini.stats.3.v":"ಸ್ಥಾಯೀ ಬೆಳವಣಿಗೆ","home.hero.title":'<span class="accent"> ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆ ಮತ್ತು ಅಭಿವೃದ್ಧಿ </span> ಮತ್ತು ಉತ್ಪನ್ನ ಅನ್ವೇಷಣೆ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸುತ್ತಿದೆ',"home.html.lang":"ಕನ್ನಡ","home.meta.description":"上海树下小屋网络科技有限公司 - ಸ್ವಾಯತ್ತ ಸಂಶೋಧನೆ ಮತ್ತು ಉತ್ಪನ್ನ ಅನ್ವೇಷಣೆಯ ಮೇಲೆ ಕೇಂದ್ರೀಕೃತವಾಗಿದೆ","home.meta.title":"上海树下小屋网络科技有限公司","home.nav.about":"ನಮ್ಮ ಬಗ್ಗೆ","home.nav.contact":"ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ","home.nav.home":"ಮನೆ","home.nav.toggle":"ಮೆನು ವಿಸ್ತಾರಗೊಳಿಸಿ","home.noscript":"ಈ ತಾಣವು ಸಂಪೂರ್ಣ ಪರಸ್ಪರ ಅನುಭವಕ್ಕಾಗಿ (ನಾವಿಗೇಶನ್ ಮೆನು, ಸ್ಕ್ರೋಲಿಂಗ್ ಪರಿಣಾಮಗಳು, ಇತ್ಯಾದಿ) ಜಾವಾಸ್ಕ್ರಿಪ್ಟ್ ಅನ್ನು ಅಗತ್ಯವಿದೆ.","nav.apps":"ಆ್ಯಪ್ ಸೆಂಟರ್","nav.support":"ಬೆಂಬಲ","apps.hero.eyebrow":"sxxw.site · ಆ್ಯಪ್ ಬೆಂಬಲ ಕೇಂದ್ರ","apps.hero.title":"ಪ್ರತಿ ಆ್ಯಪ್ ಸ್ಪಷ್ಟ ಮಾರ್ಗದರ್ಶನ ಮತ್ತು ನೀವು ನಿಯಂತ್ರಿಸುವ ಡೇಟಾ ಗಡಿಗಳೊಂದಿಗೆ ಬರುತ್ತದೆ.","apps.hero.desc":"ಇಲ್ಲಿ ಉತ್ಪನ್ನದ ಅವಲೋಕನ, ಆರಂಭಿಕ ಮಾರ್ಗದರ್ಶಿಗಳು, ಗೌಪ್ಯತಾ ನೀತಿ, ನಿಯಮಗಳು ಮತ್ತು ತಾಂತ್ರಿಕ ಬೆಂಬಲ ಸಿಗುತ್ತದೆ. ನೀವು ನಿಜವಾಗಿ ಬಳಸುವ ವೇದಿಕೆಯ ವಿಭಾಗವನ್ನು ಓದಿ.","apps.card.cta":"ಆ್ಯಪ್ ನೋಡಿ","apps.memoria.desc":"ಹುಟ್ಟುಹಬ್ಬ, ವಾರ್ಷಿಕೋತ್ಸವ ಮತ್ತು ಕೌಂಟ್‌ಡೌನ್‌ಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ. iOS ಆವೃತ್ತಿ ಐಚ್ಛಿಕ ಖಾಸಗಿ iCloud ಸಿಂಕ್ ಬೆಂಬಲಿಸುತ್ತದೆ; Huawei AppGallery-ನ Memoria ಆವೃತ್ತಿ ಸಂಪೂರ್ಣವಾಗಿ ಸಾಧನದಲ್ಲೇ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.","apps.memoria.tag":"ವಾರ್ಷಿಕೋತ್ಸವ · ಜ್ಞಾಪನೆಗಳು","apps.timetrails.desc":"ಗೌಪ್ಯತೆ-ಮೊದಲ GPS ಟ್ರ್ಯಾಕ್ ಲಾಗಿಂಗ್: ಪ್ರಯಾಣ, ವ್ಯಾಯಾಮ ಮತ್ತು ಸಂಚಾರಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ದಾಖಲಿಸುತ್ತದೆ, ನಕ್ಷೆಯಲ್ಲಿ ನಿಮ್ಮ ಹೆಜ್ಜೆಗುರುತುಗಳನ್ನು ಬಿಡಿಸುತ್ತದೆ ಮತ್ತು ನೀವು ಭೇಟಿ ನೀಡಿದ ನಗರಗಳನ್ನು ಬೆಳಗಿಸುತ್ತದೆ. ಟ್ರ್ಯಾಕ್‌ಗಳು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಸಾಧನದಲ್ಲೇ ಇರುತ್ತವೆ, ಐಚ್ಛಿಕ ಖಾಸಗಿ iCloud ಬ್ಯಾಕಪ್‌ನೊಂದಿಗೆ.","apps.timetrails.tag":"GPS ಟ್ರ್ಯಾಕ್ · ಮಾರ್ಗಗಳು","apps.traceapp.desc":"ಮಾರ್ಗ, ದೂರ, ವೇಗ ಮತ್ತು ಪೇಸ್ ದಾಖಲಿಸುತ್ತದೆ. ಖಾತೆ ಇಲ್ಲ, ಬಿಲ್ಟ್-ಇನ್ ಜಾಹೀರಾತು ಅಥವಾ ಮೂರನೇ ಪಕ್ಷದ ಅನಾಲಿಟಿಕ್ಸ್ ಇಲ್ಲ.","apps.traceapp.tag":"ಮಾರ್ಗಗಳು · ಅಂಕಿಅಂಶ","apps.footer.slogan":"ಉತ್ಪನ್ನಗಳು · ಮಾರ್ಗದರ್ಶಿಗಳು · ಗೌಪ್ಯತೆ ಮತ್ತು ಬೆಂಬಲ","support.brand":"ಬೆಂಬಲ","support.hero.eyebrow":"sxxw.site · ಬೆಂಬಲ ಕೇಂದ್ರ","support.hero.title":"ನಿಮಗೆ ಸೂಕ್ತವಾದ ರೀತಿಯಲ್ಲಿ TreeHouse ಅನ್ನು ಸಂಪರ್ಕಿಸಿ.","support.hero.desc":"TreeHouse ಆ್ಯಪ್‌ಗಳ ಎಲ್ಲಾ ಅಧಿಕೃತ ಬೆಂಬಲ ಚಾನೆಲ್‌ಗಳು ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ: ಪ್ರತಿಕ್ರಿಯೆ, ಆ್ಯಪ್-ಸ್ಟೋರ್ ವಿಮರ್ಶೆಗಳು ಮತ್ತು ಅಧಿಕೃತ ಸಮುದಾಯ ಗುಂಪುಗಳು. ಲೋಕಲ್-ಫಸ್ಟ್, ಜಾಹೀರಾತಿಲ್ಲ, ಮೂರನೇ ಪಕ್ಷದ ಟ್ರ್ಯಾಕಿಂಗ್ ಇಲ್ಲ.","support.g1.title":"ಪ್ರತಿಕ್ರಿಯೆ","support.g1.note":"ಸಮಸ್ಯೆ ಎದುರಾಯಿತೇ ಅಥವಾ ಸಲಹೆ ಇದೆಯೇ? ಕೆಳಗಿನ ಯಾವುದೇ ವಿಧಾನದಲ್ಲಿ ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ — ನಾವು ಪ್ರತಿ ಸಂದೇಶವನ್ನೂ ಓದುತ್ತೇವೆ.","support.g1.feedback.name":"ಆ್ಯಪ್ ಒಳಗಿನ ಪ್ರತಿಕ್ರಿಯೆ","support.g1.feedback.desc":"ಪ್ರತಿ ಆ್ಯಪ್ ಒಳಗಿನಿಂದಲೇ ಕಳುಹಿಸಿ; ನಿಮ್ಮ ಆವೃತ್ತಿ, ಸಾಧನ ಮತ್ತು ಸಿಸ್ಟಮ್ ಮಾಹಿತಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಲಗತ್ತಾಗುತ್ತದೆ, ಇದರಿಂದ ನಾವು ಬೇಗ ಪರಿಶೀಲಿಸಬಹುದು.","support.g1.feedback.cta":"ಆ್ಯಪ್‌ಗಳನ್ನು ನೋಡಿ","support.g1.email.name":"ಇಮೇಲ್ ಕಳುಹಿಸಿ","support.g1.email.desc":"ಔಪಚಾರಿಕ ವಿನಂತಿಗಳು ಮತ್ತು ಗೌಪ್ಯತೆ ಅಥವಾ ಖಾತೆ ವಿಷಯಗಳಿಗೆ ಇಮೇಲ್‌ನಲ್ಲಿ ಹೆಚ್ಚು ಸಂಪೂರ್ಣ ಉತ್ತರ ಸಿಗುತ್ತದೆ.","support.g1.email.cta":"ಇಮೇಲ್ ಕಳುಹಿಸಿ","support.g2.title":"ಆ್ಯಪ್‌ಗಳಿಗೆ ರೇಟಿಂಗ್ ನೀಡಿ (ಪ್ರತಿ ಆ್ಯಪ್‌ಗೆ)","support.g2.note":"ಇಷ್ಟವಾದರೆ ನೀವು ಬಳಸುವ ಸ್ಟೋರ್‌ನಲ್ಲಿ ವಿಮರ್ಶೆ ಬರೆಯಿರಿ — ನಾವು ನೋಡುತ್ತೇವೆ ಮತ್ತು ಉತ್ತರಿಸುತ್ತೇವೆ. ನಿಮ್ಮ ಆ್ಯಪ್‌ಗೆ ಹೊಂದುವುದನ್ನು ಟ್ಯಾಪ್ ಮಾಡಿ.","support.g2.cta.write":"ವಿಮರ್ಶೆ ಬರೆಯಿರಿ","support.g2.cta.goto":"ವಿಮರ್ಶೆಗೆ ಹೋಗಿ","support.g2.memoria.huawei.platform":"HarmonyOS · Huawei ಸಾಧನಗಳು","support.g3.title":"WeChat · QQ · Telegram ಗುಂಪುಗಳು","support.g3.note":"ನವೀಕರಣಗಳು ಮತ್ತು ಸಹ-ಬಳಕೆದಾರರ ಸಹಾಯಕ್ಕಾಗಿ ನಮ್ಮ ಅಧಿಕೃತ ಗುಂಪುಗಳಿಗೆ ಸೇರಿ: ಚೀನಾದಲ್ಲಿ WeChat / QQ, ಬೇರೆಡೆ Telegram.","support.g3.wechat.name":"WeChat ಗುಂಪು","support.g3.wechat.desc":"ದೈನಂದಿನ ಚಾಟ್ ಮತ್ತು ಸಹಾಯ. ಗುಂಪು ತುಂಬಿದಾಗ ಹೊಸ QR ಕೋಡ್ ಪೋಸ್ಟ್ ಮಾಡಲಾಗುತ್ತದೆ.","support.g3.qq.name":"QQ ಗುಂಪು","support.g3.qq.desc":"ಚೀನಾದ ಬಳಕೆದಾರರಿಗೆ; ಹೆಚ್ಚಿನ ಸದಸ್ಯ ಸಾಮರ್ಥ್ಯ.","support.g3.tg.name":"Telegram ಗುಂಪು","support.g3.tg.desc":"ಅಂತರರಾಷ್ಟ್ರೀಯ ಬಳಕೆದಾರರಿಗೆ ಚಾಟ್ ಮತ್ತು ಪ್ರಶ್ನೋತ್ತರ.","support.g3.join":"ಸೇರಿ","support.pending":"ಶೀಘ್ರದಲ್ಲೇ","support.foot":"ಸರಿಯಾದ ಚಾನೆಲ್ ಸಿಗಲಿಲ್ಲವೇ? house@sxxw.site ಗೆ ಇಮೇಲ್ ಮಾಡಿ, ನಾವು ಉತ್ತರಿಸುತ್ತೇವೆ.","support.footer.slogan":"ಪ್ರತಿಕ್ರಿಯೆ · ಆ್ಯಪ್-ಸ್ಟೋರ್ ವಿಮರ್ಶೆಗಳು · ಸಮುದಾಯ ಗುಂಪುಗಳು"};export{e as default};
